"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["70398"],{79087(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.fase_sem_banca_da_segunda_instancia","status":422,"titulo":"O recurso admite inst\xe2ncia superior, e a fase n\xe3o prev\xea banca que o julgue em 2\xaa inst\xe2ncia"},"descricao":{"codigo":"uniplus.selecao.banca.fase_sem_banca_da_segunda_instancia","requisitos":["UNI-REQ-0274","UNI-REQ-0454"],"oQueAconteceu":["O recurso da fase declara que admite inst\xe2ncia superior, e a pr\xf3pria fase n\xe3o\\nprev\xea uma banca com o papel de julgar o recurso em 2\xaa inst\xe2ncia (UNI-REQ-0454).\\nN\xe3o servem a banca de uma etapa da fase nem a banca de an\xe1lise de recursos de 1\xaa\\ninst\xe2ncia: a 2\xaa inst\xe2ncia \xe9 outra banca, de papel pr\xf3prio.","O papel \xe9 registrado na banca quando ela \xe9 criada, e a confer\xeancia olha esse\\npapel, e n\xe3o o nome do tipo. A configura\xe7\xe3o n\xe3o diz qual \xf3rg\xe3o \xe9 a 2\xaa inst\xe2ncia:\\nquem a integra \xe9 definido na designa\xe7\xe3o da banca.","A mensagem cita a fase pelo c\xf3digo. A confer\xeancia \xe9 de completude e roda na\\npublica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico. A recusa vem como o c\xf3digo desta p\xe1gina\\nno corpo da resposta, e n\xe3o na lista `errors[]`, e aponta o campo\\n`fases[i].bancasRequeridas`. O item fica sem confer\xeancia, e a recusa n\xe3o sai,\\nenquanto parte das bancas ou dos recursos da fase estiver recusada por outro\\nmotivo, ou quando o recurso j\xe1 foi recusado pelo\\n[tipo que n\xe3o admite inst\xe2ncia superior](/erros/uniplus.selecao.banca.tipo_nao_admite_instancia_superior)."],"comoResolver":["Escolha um dos caminhos:","- acrescente \xe0 fase uma banca com o papel \\"Julga o recurso em 2\xaa inst\xe2ncia\\"; ela\\n  declara a regra de delibera\xe7\xe3o do edital e n\xe3o define candidatos atendidos\\n  ([regra obrigat\xf3ria](/erros/uniplus.selecao.banca.regra_de_deliberacao_obrigatoria),\\n  [candidatos atendidos](/erros/uniplus.selecao.banca.candidatos_atendidos_em_banca_de_recursos));\\n- ou declare que o recurso n\xe3o admite inst\xe2ncia superior.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_instancia_superior_com_banca_da_segunda_instancia`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);